/*
 * ==================== FLOW 1: CLIENT READ WITH SINGLEFLIGHT =========================
 *
 * Thread 1..1000 call getOrLoad("product:99")
 *   -> Check ConsistentHashRing.getShard("product:99") -> Shard 2
 *   -> Network GET "product:99" -> Cache Miss!
 *   -> Thread 1 registers CompletableFuture in inFlightLoads["product:99"] & queries DB
 *   -> Threads 2..1000 see existing CompletableFuture & wait without hitting DB
 *   -> Thread 1 receives DB result -> SET "product:99" on Shard 2 -> Completes Future
 *
 * ==================== FLOW 2: SERVER SEGMENTED O(1) LRU + TTL =======================
 *
 * Shard receives GET/SET("product:99")
 *   -> Route to Segment[hash("product:99") & 15]
 *   -> Acquire fine-grained Segment StampedLock/ReentrantLock
 *   -> Lookup Node in HashMap -> Check TTL -> Move to Doubly-Linked List Head
 *   -> Evict from Tail if currentBytes > maxSegmentBytes
 */

package com.sdi.cache.engine;

import com.sdi.cache.core.CacheEntryNode;
import com.sdi.cache.core.ShardNode;

import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.Supplier;

// ---------------- FLOW 1: CONSISTENT HASH RING & SINGLEFLIGHT CLIENT ----------------
public class ConsistentHashCacheClient {

    private static final int VIRTUAL_NODES_PER_SHARD = 150;
    private final NavigableMap<Long, ShardNode> ring = new TreeMap<>();
    private final ConcurrentHashMap<String, CompletableFuture<byte[]>> inFlightLoads = new ConcurrentHashMap<>();

    public synchronized void addShard(ShardNode shard) {
        for (int i = 0; i < VIRTUAL_NODES_PER_SHARD; i++) {
            long hash = murmurHash64(shard.shardId() + "#vnode" + i);
            ring.put(hash, shard);
        }
    }

    public synchronized void removeShard(ShardNode shard) {
        for (int i = 0; i < VIRTUAL_NODES_PER_SHARD; i++) {
            long hash = murmurHash64(shard.shardId() + "#vnode" + i);
            ring.remove(hash);
        }
    }

    public ShardNode routeKey(String key) {
        long hash = murmurHash64(key);
        Map.Entry<Long, ShardNode> entry = ring.ceilingEntry(hash);
        return (entry != null) ? entry.getValue() : ring.firstEntry().getValue();
    }

    // Stampede-protected read-through using Singleflight request coalescing
    public byte[] getOrLoad(String key, Duration ttl, Supplier<byte[]> dbLoader,
                            SegmentedLruShardEngine shardTransport) {
        byte[] cached = shardTransport.get(key);
        if (cached != null) {
            return cached;
        }

        CompletableFuture<byte[]> newFuture = new CompletableFuture<>();
        CompletableFuture<byte[]> existing = inFlightLoads.putIfAbsent(key, newFuture);

        if (existing != null) {
            // Another thread on this node is already loading this key from DB; coalesce!
            return existing.join();
        }

        try {
            byte[] freshValue = dbLoader.get();
            if (freshValue != null) {
                shardTransport.set(key, freshValue, ttl.toMillis());
            }
            newFuture.complete(freshValue);
            return freshValue;
        } catch (Throwable t) {
            newFuture.completeExceptionally(t);
            throw t;
        } finally {
            inFlightLoads.remove(key);
        }
    }

    private static long murmurHash64(String key) {
        byte[] bytes = key.getBytes(StandardCharsets.UTF_8);
        long h = 0xcbf29ce484222325L;
        for (byte b : bytes) {
            h ^= (b & 0xff);
            h *= 0x100000001b3L;
        }
        return h;
    }
}

// ---------------- FLOW 2: SERVER-SIDE SEGMENTED O(1) LRU + TTL ENGINE ----------------
public class SegmentedLruShardEngine {

    private static final int SEGMENT_COUNT = 16; // Must be power of 2
    private final Segment[] segments = new Segment[SEGMENT_COUNT];

    public SegmentedLruShardEngine(long totalMaxBytes) {
        long perSegmentBytes = totalMaxBytes / SEGMENT_COUNT;
        for (int i = 0; i < SEGMENT_COUNT; i++) {
            segments[i] = new Segment(perSegmentBytes);
        }
    }

    private Segment segmentFor(String key) {
        int h = key.hashCode();
        h ^= (h >>> 16);
        return segments[h & (SEGMENT_COUNT - 1)];
    }

    public byte[] get(String key) {
        return segmentFor(key).get(key, System.currentTimeMillis());
    }

    public void set(String key, byte[] value, long ttlMs) {
        segmentFor(key).set(key, value, ttlMs, System.currentTimeMillis());
    }

    private static final class Segment {
        private final ReentrantLock lock = new ReentrantLock();
        private final Map<String, CacheEntryNode> map = new HashMap<>();
        private final CacheEntryNode head = new CacheEntryNode(null, null, 0, 0);
        private final CacheEntryNode tail = new CacheEntryNode(null, null, 0, 0);
        private final long maxBytes;
        private long currentBytes = 0;

        Segment(long maxBytes) {
            this.maxBytes = maxBytes;
            head.next = tail;
            tail.prev = head;
        }

        byte[] get(String key, long nowMs) {
            lock.lock();
            try {
                CacheEntryNode node = map.get(key);
                if (node == null) {
                    return null;
                }
                if (node.isExpired(nowMs)) {
                    removeNode(node);
                    return null;
                }
                moveToHead(node);
                return node.valueBytes;
            } finally {
                lock.unlock();
            }
        }

        void set(String key, byte[] value, long ttlMs, long nowMs) {
            long expireAt = (ttlMs > 0) ? (nowMs + ttlMs) : 0L;
            lock.lock();
            try {
                CacheEntryNode existing = map.get(key);
                if (existing != null) {
                    currentBytes -= existing.valueBytes.length;
                    existing.valueBytes = value;
                    existing.expireAtMs = expireAt;
                    existing.version++;
                    currentBytes += value.length;
                    moveToHead(existing);
                } else {
                    CacheEntryNode newNode = new CacheEntryNode(key, value, expireAt, 1L);
                    map.put(key, newNode);
                    addToHead(newNode);
                    currentBytes += key.length() + value.length;
                }
                // Evict Least Recently Used (from tail.prev) while over capacity
                while (currentBytes > maxBytes && tail.prev != head) {
                    removeNode(tail.prev);
                }
            } finally {
                lock.unlock();
            }
        }

        private void addToHead(CacheEntryNode node) {
            node.next = head.next;
            node.prev = head;
            head.next.prev = node;
            head.next = node;
        }

        private void unlink(CacheEntryNode node) {
            node.prev.next = node.next;
            node.next.prev = node.prev;
        }

        private void moveToHead(CacheEntryNode node) {
            unlink(node);
            addToHead(node);
        }

        private void removeNode(CacheEntryNode node) {
            unlink(node);
            map.remove(node.key);
            currentBytes -= (node.key.length() + node.valueBytes.length);
        }
    }
}

// 1. Dispatch Multi-Channel Notification
POST /api/v1/notifications/send
Headers:
  Idempotency-Key: ord_99102_shipped
Request:
{
