/*
 * ==================== FLOW 1: IDEMPOTENT INGESTION & ROUTING =========================
 *
 * Producer -> POST /send (idempotencyKey="abc-123")
 *   -> Redis SETNX "idem:abc-123" (If exists -> return cached ACCEPTED response)
 *   -> Fetch UserPreference & DeviceTokens from Redis/Postgres
 *   -> For each requested Channel:
 *        - If priority != CRITICAL and (channel opted-out OR in user's local Quiet Hours):
 *            skip/defer channel
 *        - Else: publish ChannelDispatchEvent to "notif.{priority}.{channel}" Kafka topic
 *
 * ==================== FLOW 2: WORKER DISPATCH, FAILOVER & RETRY ======================
 *
 * Worker consumes ChannelDispatchEvent from Kafka
 *   -> Check Redis "sent:{idempotencyKey}:{channel}:{target}" (Prevent duplicate send on rebalance)
 *   -> Render localized Template
 *   -> Dispatch to Primary Provider (e.g., Twilio / APNs)
 *        |-- 200 OK -> Mark "sent:..." in Redis, log SENT in Cassandra
 *        |-- 410 Gone (APNs Unregistered Token) -> Mark device token invalid in DB, do NOT retry
 *        +-- 429 / 5xx Transient Error:
 *              - If CRITICAL SMS -> Immediately failover to Secondary Provider (AWS SNS)
 *              - Else if attempt < 3 -> Forward to tiered retry topic (1m -> 5m -> 30m)
 *              - Else -> Route to Dead Letter Queue (DLQ) & trigger PagerDuty alert
 */

package com.sdi.notification.service;

import com.sdi.notification.domain.*;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;

import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

@Service
public class NotificationPipelineService {

    private final StringRedisTemplate redis;
    private final UserPreferenceRepository prefRepo;
    private final TemplateEngine templateEngine;
    private final KafkaTemplate<String, ChannelDispatchEvent> kafka;
    private final SmsProviderClient twilioClient;
    private final SmsProviderClient snsFallbackClient;

    public NotificationPipelineService(StringRedisTemplate redis,
                                       UserPreferenceRepository prefRepo,
                                       TemplateEngine templateEngine,
                                       KafkaTemplate<String, ChannelDispatchEvent> kafka,
                                       SmsProviderClient twilioClient,
                                       SmsProviderClient snsFallbackClient) {
        this.redis = redis;
        this.prefRepo = prefRepo;
        this.templateEngine = templateEngine;
        this.kafka = kafka;
        this.twilioClient = twilioClient;
        this.snsFallbackClient = snsFallbackClient;
    }

    // ---------------- FLOW 1: INGESTION, PREFERENCE & QUIET HOURS FILTER ----------------
    public SendNotificationResponse ingest(SendNotificationRequest req) {
        String idemKey = "idem:" + req.idempotencyKey();
        Boolean isFirstSeen = redis.opsForValue().setIfAbsent(idemKey, "1", Duration.ofHours(24));
        if (Boolean.FALSE.equals(isFirstSeen)) {
            return new SendNotificationResponse("DEDUPED", req.idempotencyKey(),
                    DeliveryStatus.ACCEPTED, List.of());
        }

        UserPreferenceEntity pref = prefRepo.getPreferences(req.userId());
        List<DeviceToken> devices = prefRepo.getActiveDevices(req.userId());
        String notificationId = UUID.randomUUID().toString();
        List<Channel> scheduled = new ArrayList<>();

        boolean inQuietHours = isUserInQuietHours(pref);

        for (Channel channel : req.channels()) {
            // CRITICAL notifications (OTPs, security alerts) bypass opt-out & quiet hours
            if (req.priority() != Priority.CRITICAL) {
                if (inQuietHours || !isChannelOptedIn(pref, channel)) {
                    continue;
                }
            }

            List<String> targets = resolveTargets(pref, devices, channel);
            for (String target : targets) {
                ChannelDispatchEvent event = new ChannelDispatchEvent(
                        notificationId, req.idempotencyKey(), req.userId(),
                        channel, req.priority(), target,
                        req.templateId(), req.locale(), req.variables(), 1
                );
                String topic = buildTopicName(req.priority(), channel);
                kafka.send(topic, String.valueOf(req.userId()), event);
                scheduled.add(channel);
            }
        }

        return new SendNotificationResponse(
                notificationId, req.idempotencyKey(), DeliveryStatus.QUEUED, scheduled);
    }

    private boolean isUserInQuietHours(UserPreferenceEntity pref) {
        int localHour = ZonedDateTime.now(ZoneId.of(pref.timezone())).getHour();
        if (pref.quietStartHour() > pref.quietEndHour()) {
            // Overnight window, e.g., 22:00 to 08:00
            return localHour >= pref.quietStartHour() || localHour < pref.quietEndHour();
        }
        return localHour >= pref.quietStartHour() && localHour < pref.quietEndHour();
    }

    private boolean isChannelOptedIn(UserPreferenceEntity pref, Channel channel) {
        return switch (channel) {
            case IOS_PUSH, ANDROID_PUSH -> pref.pushEnabled();
            case EMAIL -> pref.emailEnabled();
            case SMS -> pref.smsEnabled();
            case IN_APP -> true;
        };
    }

    private List<String> resolveTargets(UserPreferenceEntity pref, List<DeviceToken> devices, Channel ch) {
        return switch (ch) {
            case EMAIL -> List.of(pref.email());
            case SMS -> List.of(pref.phoneE164());
            case IOS_PUSH, ANDROID_PUSH -> devices.stream()
                    .filter(d -> d.platform() == ch)
                    .map(DeviceToken::pushToken)
                    .toList();
            case IN_APP -> List.of(String.valueOf(pref.userId()));
        };
    }

    private String buildTopicName(Priority p, Channel c) {
        return "notif." + p.name().toLowerCase() + "." + c.name().toLowerCase();
    }

    // ---------------- FLOW 2: WORKER DISPATCH, VENDOR FAILOVER & RETRY ----------------
    @KafkaListener(topics = {"notif.critical.sms", "notif.high.sms"}, groupId = "sms-workers")
    public void consumeSmsEvent(ChannelDispatchEvent event) {
        // Guard against duplicate delivery caused by Kafka consumer rebalance
        String sentDedupKey = "sent:" + event.idempotencyKey() + ":" + event.targetAddress();
        if (Boolean.TRUE.equals(redis.hasKey(sentDedupKey))) {
            return;
        }

        String renderedBody = templateEngine.render(event.templateId(), event.locale(), event.variables());

        try {
            twilioClient.sendSms(event.targetAddress(), renderedBody);
            redis.opsForValue().set(sentDedupKey, "SENT", Duration.ofHours(24));
        } catch (TransientProviderException ex) {
            if (event.priority() == Priority.CRITICAL) {
                // Immediate multi-vendor failover for P0 OTPs!
                snsFallbackClient.sendSms(event.targetAddress(), renderedBody);
                redis.opsForValue().set(sentDedupKey, "SENT_FALLBACK", Duration.ofHours(24));
            } else {
                scheduleExponentialRetry(event);
            }
        }
    }

    private void scheduleExponentialRetry(ChannelDispatchEvent event) {
        int nextAttempt = event.attempt() + 1;
        ChannelDispatchEvent retryEvent = new ChannelDispatchEvent(
                event.notificationId(), event.idempotencyKey(), event.userId(),
                event.channel(), event.priority(), event.targetAddress(),
                event.templateId(), event.locale(), event.variables(), nextAttempt
        );

        String nextTopic = switch (nextAttempt) {
            case 2 -> "notif.retry.1m";
            case 3 -> "notif.retry.5m";
            case 4 -> "notif.retry.30m";
            default -> "notif.dlq";
        };
        kafka.send(nextTopic, String.valueOf(event.userId()), retryEvent);
    }
}

