/*
 * ==================== FLOW 1: REAL-TIME SEND & MULTI-DEVICE FAN-OUT ==================
 *
 * User A --(WSS SEND_MSG)--> Gateway 12 --(gRPC)--> ChatRoutingService
 *   1. Idempotency check on clientMsgUuid
 *   2. Generate Snowflake messageId (e.g., 1849201928301L)
 *   3. Save ChatMessageEntity to Cassandra ((channelId, 202609), messageId)
 *   4. Return SERVER_ACK(messageId) to User A
 *   5. Resolve recipients (for groups <= 500: fetch member list; for > 500: publish to Pub/Sub)
 *   6. For each member (including Sender's other linked devices!):
 *        - Query Redis HGETALL "sess:{memberId}" -> Map<deviceId, gatewayNodeId>
 *        - Push NEW_MSG frame to each online gatewayNodeId via gRPC
 *        - If member has no active mobile socket -> emit event to Kafka "offline-push"
 *
 * ==================== FLOW 2: OFFLINE RECONNECTION SYNC ==============================
 *
 * User B reconnects WebSocket -> Registers session in Redis HSET "sess:userB" "ios" "gw-44"
 *   -> Client requests syncMissedMessages(channelId, lastSeenMessageId=1849200000000L)
 *   -> Query Cassandra PK=(channelId, currentBucket) AND message_id > 1849200000000L
 *   -> Stream ordered messages back to User B
 */

package com.sdi.chat.service;

import com.sdi.chat.domain.*;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.time.YearMonth;
import java.util.List;
import java.util.Map;

@Service
public class ChatRoutingService {

    private static final int SMALL_GROUP_FANOUT_THRESHOLD = 500;

    private final SnowflakeIdGenerator idGenerator;
    private final CassandraMessageRepository messageRepo;
    private final GroupMembershipCache groupCache;
    private final StringRedisTemplate redis;
    private final ChatGatewayRpcClient gatewayRpc;
    private final KafkaTemplate<String, String> kafka;

    public ChatRoutingService(SnowflakeIdGenerator idGenerator,
                              CassandraMessageRepository messageRepo,
                              GroupMembershipCache groupCache,
                              StringRedisTemplate redis,
                              ChatGatewayRpcClient gatewayRpc,
                              KafkaTemplate<String, String> kafka) {
        this.idGenerator = idGenerator;
        this.messageRepo = messageRepo;
        this.groupCache = groupCache;
        this.redis = redis;
        this.gatewayRpc = gatewayRpc;
        this.kafka = kafka;
    }

    // ---------------- FLOW 1: REAL-TIME MESSAGE PERSISTENCE & FAN-OUT ----------------
    public WebSocketFrame handleIncomingMessage(long senderUserId, String senderDeviceId, WebSocketFrame incoming) {
        // 1. Generate time-ordered 64-bit Snowflake ID & compute monthly partition bucket
        long messageId = idGenerator.nextId();
        int bucketYyyymm = computeCurrentBucket();
        long nowMs = Instant.now().toEpochMilli();

        // 2. Durable write to Cassandra (Write-Once per channel, never duplicated per member)
        ChatMessageEntity entity = new ChatMessageEntity(
                incoming.channelId(), bucketYyyymm, messageId, senderUserId,
                incoming.clientMsgUuid(), incoming.content(), incoming.mediaUrl(),
                Instant.ofEpochMilli(nowMs)
        );
        messageRepo.save(entity);

        WebSocketFrame outboundFrame = new WebSocketFrame(
                FrameType.NEW_MSG, incoming.clientMsgUuid(), incoming.channelId(),
                messageId, senderUserId, incoming.content(), incoming.mediaUrl(), nowMs
        );

        // 3. Hybrid Fan-Out based on Channel Size
        int memberCount = groupCache.getMemberCount(incoming.channelId());
        if (memberCount > SMALL_GROUP_FANOUT_THRESHOLD) {
            // Large Discord-style channel (>500 members): publish once to Gateway Pub/Sub topic
            redis.convertAndSend("chat:chan:" + incoming.channelId(), serialize(outboundFrame));
        } else {
            // 1-on-1 or WhatsApp-style group (<=500 members): direct device fan-out
            List<Long> memberIds = groupCache.getChannelMembers(incoming.channelId());
            for (long memberId : memberIds) {
                deliverToUserDevices(memberId, senderUserId, senderDeviceId, outboundFrame);
            }
        }

        // 4. Return SERVER_ACK to the sending device with the canonical server messageId
        return new WebSocketFrame(
                FrameType.SERVER_ACK, incoming.clientMsgUuid(), incoming.channelId(),
                messageId, senderUserId, null, null, nowMs
        );
    }

    private void deliverToUserDevices(long targetUserId, long senderUserId,
                                      String senderDeviceId, WebSocketFrame frame) {
        // Fetch all active devices for targetUserId from Redis Hash: "sess:{userId}"
        Map<Object, Object> deviceToGateway = redis.opsForHash().entries("sess:" + targetUserId);
        boolean deliveredToMobile = false;

        for (Map.Entry<Object, Object> entry : deviceToGateway.entrySet()) {
            String deviceId = (String) entry.getKey();
            String gatewayNodeId = (String) entry.getValue();

            // Skip echoing back to the exact same device that sent the message
            if (targetUserId == senderUserId && deviceId.equals(senderDeviceId)) {
                continue;
            }

            boolean pushed = gatewayRpc.pushFrameToDevice(gatewayNodeId, targetUserId, deviceId, frame);
            if (!pushed) {
                // Stale socket detected: clean up dead device entry from Redis
                redis.opsForHash().delete("sess:" + targetUserId, deviceId);
            } else if (deviceId.startsWith("ios_") || deviceId.startsWith("android_")) {
                deliveredToMobile = true;
            }
        }

        // If recipient is offline on mobile, trigger APNs/FCM push notification via Kafka
        if (targetUserId != senderUserId && !deliveredToMobile) {
            kafka.send("chat-offline-push", String.valueOf(targetUserId),
                    "{\"userId\":" + targetUserId + ",\"channelId\":" + frame.channelId() + "}");
        }
    }

    // ---------------- FLOW 2: OFFLINE RECONNECTION HISTORY SYNC ----------------
    public List<ChatMessageEntity> syncMissedMessages(long channelId, long afterMessageId, int limit) {
        int currentBucket = computeCurrentBucket();
        // Fast sequential scan on Cassandra clustering key (message_id > afterMessageId)
        return messageRepo.findMessagesAfter(channelId, currentBucket, afterMessageId, limit);
    }

    private int computeCurrentBucket() {
        YearMonth ym = YearMonth.now();
        return ym.getYear() * 100 + ym.getMonthValue();
    }

    private String serialize(WebSocketFrame frame) {
        return frame.channelId() + "|" + frame.messageId() + "|" + frame.senderId() + "|" + frame.content();
    }
}

