        chunk_size_bytes       INT (~4MB)
}

// Relationships: files_metadata --(1 : N (version history))--> file_versions --(1 : N (ordered 4MB chunks))--> chunk_manifests

/*
================================================================================
FLOW 1: CONTENT-DEFINED CHUNKING (RABIN ROLLING HASH) + CAS DEDUP UPLOAD
================================================================================
Original File : [ Chunk 0 (4.1MB) | Chunk 1 (3.8MB) | Chunk 2 (4.5MB) ]
10KB Edit in 0: [ Chunk 0' (4.11MB)| Chunk 1 (SAME!) | Chunk 2 (SAME!) ]
1. Client runs Rabin Chunker -> Computes SHA-256 for [Chunk 0', Chunk 1, Chunk 2]
2. POST /files/revisions/init -> Server checks cas_blocks table:
   - Chunk 1 & Chunk 2 ALREADY EXIST -> Skipped!
   - Chunk 0' MISSING -> Server returns Presigned S3 PUT URL for Chunk 0' only.
3. Client uploads Chunk 0' directly to S3 -> Calls POST /commit.

================================================================================
FLOW 2: ATOMIC REVISION COMMIT & CONFLICT COPY BRANCHING
================================================================================
Device A & Device B both start at baseVersion = 4.
1. Device A commits first -> DB CAS (curr_version: 4 -> 5), LSN = 1092.
2. Device B commits with expectedBaseVersion = 4 -> DB CAS sees curr_version (5) != 4!
3. Server automatically creates "report (Conflicted Copy).pdf" at version 1, LSN = 1093.
4. SSE Notification pushes LSN 1093 -> Both devices sync both files cleanly.
*/

package com.sdi.filestorage.service;

import com.sdi.filestorage.domain.*;
import java.security.MessageDigest;
import java.time.Instant;
import java.time.LocalDate;
import java.util.*;

public class FileSyncEngine {

    // Rabin-Karp Content-Defined Chunking constants
    private static final int MIN_CHUNK_SIZE = 2 * 1024 * 1024; // 2 MB
    private static final int MAX_CHUNK_SIZE = 8 * 1024 * 1024; // 8 MB
    private static final long AVG_CHUNK_MASK = (1L << 22) - 1; // 4 MB average cut-point

    /**
     * FLOW 1 (Client-Side SDK): Content-Defined Chunking via Rolling Hash
     */
    public List<BlockDescriptor> splitFileContentDefined(byte[] fileBytes) throws Exception {
        List<BlockDescriptor> blocks = new ArrayList<>();
        int chunkStart = 0;
        long rollingHash = 0;
        int blockIndex = 0;

        for (int i = 0; i < fileBytes.length; i++) {
            rollingHash = (rollingHash * 31 + (fileBytes[i] & 0xFF));
            int currentChunkLen = i - chunkStart + 1;

            boolean isCutPoint = (currentChunkLen >= MIN_CHUNK_SIZE && (rollingHash & AVG_CHUNK_MASK) == 0)
                              || (currentChunkLen >= MAX_CHUNK_SIZE)
                              || (i == fileBytes.length - 1);

            if (isCutPoint) {
                MessageDigest digest = MessageDigest.getInstance("SHA-256");
                digest.update(fileBytes, chunkStart, currentChunkLen);
                String sha256Hex = HexFormat.of().formatHex(digest.digest());

                blocks.add(new BlockDescriptor(blockIndex++, sha256Hex, currentChunkLen));
                chunkStart = i + 1;
                rollingHash = 0;
            }
        }
        return blocks;
    }

    /**
     * FLOW 2 (Server-Side): Atomic OCC Revision Commit with Automatic Conflict Copy Forking
     */
    public WorkspaceDeltaEvent commitRevisionTransactional(
        MetadataRepository repo,
        NotificationBus notificationBus,
        UUID workspaceId,
        UUID fileId,
        int expectedBaseVersion,
        List<BlockDescriptor> blocks,
        long userId
    ) {
        return repo.executeInTransaction(tx -> {
            // 1. Verify all referenced CAS blocks are uploaded & VERIFIED in S3
            Set<String> hashes = new HashSet<>();
            blocks.forEach(b -> hashes.add(b.sha256Hash()));
            if (!tx.allBlocksVerified(hashes)) {
                throw new IllegalStateException("Cannot commit revision: missing unverified CAS blocks");
            }

            FileNodeEntity currentFile = tx.lockFileForUpdate(fileId);
            long nextLsn = tx.incrementWorkspaceLsn(workspaceId);

            // 2. Check Optimistic Concurrency Control (expectedBaseVersion == currentVersion)
            if (currentFile.currentVersion() == expectedBaseVersion) {
                int newVersion = currentFile.currentVersion() + 1;
                tx.updateFileVersion(fileId, newVersion);
                tx.insertFileRevision(fileId, newVersion, nextLsn, blocks, userId);
                tx.incrementBlockRefCounts(hashes);

                WorkspaceDeltaEvent event = new WorkspaceDeltaEvent(
                    nextLsn, fileId, currentFile.fileName(), newVersion, false, blocks, Instant.now()
                );
                tx.appendWorkspaceJournal(workspaceId, event);
                notificationBus.publishWorkspaceLsn(workspaceId, nextLsn);
                return event;
            } else {
                // 3. Conflict detected! Fork into a deterministic "Conflicted Copy" file node
                UUID conflictFileId = UUID.randomUUID();
                String conflictName = buildConflictFileName(currentFile.fileName(), userId);

                tx.createFileNode(conflictFileId, workspaceId, currentFile.parentFolderId(), conflictName);
                tx.insertFileRevision(conflictFileId, 1, nextLsn, blocks, userId);
                tx.incrementBlockRefCounts(hashes);

                WorkspaceDeltaEvent conflictEvent = new WorkspaceDeltaEvent(
                    nextLsn, conflictFileId, conflictName, 1, false, blocks, Instant.now()
                );
                tx.appendWorkspaceJournal(workspaceId, conflictEvent);
                notificationBus.publishWorkspaceLsn(workspaceId, nextLsn);
                return conflictEvent;
            }
        });
    }

    private String buildConflictFileName(String originalName, long userId) {
        int dotIdx = originalName.lastIndexOf('.');
        String suffix = " (Conflicted copy " + LocalDate.now() + " by user-" + userId + ")";
        return (dotIdx == -1)
            ? originalName + suffix
            : originalName.substring(0, dotIdx) + suffix + originalName.substring(dotIdx);
    }
}

