 * FLOW 1: DRIVER LOCATION PING & ATOMIC H3 CELL MIGRATION
 * ============================================================================
 * [Driver App] --(lat,lng every 4s)--> [Location Svc] --(latLngToCell Res 8)-->
 * [Redis Lua Script: Check oldH3 != newH3 -> SREM oldCell -> SADD newCell]
 *
 * ============================================================================
 * FLOW 2: K-RING CANDIDATE SEARCH & ATOMIC DRIVER OFFER LOCKING
 * ============================================================================
 * [Rider App] --(POST /v1/trips)--> [Trip Svc (PG: REQUESTED)]
 *    --> [H3 gridDisk(pickupH3, k=1)] --> [Redis: Fetch drivers in 7 H3 cells]
 *    --> [ETA Svc: Rank top 10 by road network ETA]
 *    --> [Redis: SET lock:driver:{id} {tripId} NX EX 15]
 *    --> [Push Offer to Driver (12s window)] --(Accept)--> [PG: UPDATE Trip ACCEPTED]
 */

package com.uber.dispatch.service;

import com.uber.h3core.H3Core;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

import java.time.Duration;
import java.util.*;

@Service
public class GeospatialDispatchEngine {

    private static final int H3_RESOLUTION = 8; // ~0.73 km^2 hexagon
    private final H3Core h3;
    private final StringRedisTemplate redis;
    private final TransactionTemplate txTemplate;

    // Atomic Lua script: updates driver hash, migrates H3 cell membership if changed, sets TTL
    private static final String LUA_UPDATE_DRIVER_CELL = """
        local driverKey = KEYS[1]
        local newCellKey = KEYS[2]
        local driverId = ARGV[1]
        local newH3 = ARGV[2]
        local payloadJson = ARGV[3]
        local ttlSeconds = tonumber(ARGV[4])

        local oldH3 = redis.call('HGET', driverKey, 'h3')
        if oldH3 and oldH3 ~= newH3 then
            local oldCellKey = 'h3:cell:' .. oldH3
            redis.call('SREM', oldCellKey, driverId)
        end

        redis.call('HSET', driverKey, 'h3', newH3, 'data', payloadJson)
        redis.call('EXPIRE', driverKey, ttlSeconds)
        redis.call('SADD', newCellKey, driverId)
        redis.call('EXPIRE', newCellKey, ttlSeconds * 4)
        return 1
        """;

    public GeospatialDispatchEngine(H3Core h3, StringRedisTemplate redis, TransactionTemplate txTemplate) {
        this.h3 = h3;
        this.redis = redis;
        this.txTemplate = txTemplate;
    }

    // FLOW 1: High-throughput location ingestion (375K+ QPS)
    public void updateDriverLocation(UUID driverId, double lat, double lng, String payloadJson) {
        long h3Index = h3.latLngToCell(lat, lng, H3_RESOLUTION);
        String h3Hex = Long.toHexString(h3Index);
        String driverKey = "driver:loc:" + driverId;
        String newCellKey = "h3:cell:" + h3Hex;

        redis.execute(
            new DefaultRedisScript<>(LUA_UPDATE_DRIVER_CELL, Long.class),
            List.of(driverKey, newCellKey),
            driverId.toString(), h3Hex, payloadJson, "15"
        );
    }

    // FLOW 2: K-Ring candidate discovery + road ETA ranking + atomic driver reservation
    public Optional<UUID> matchAndLockDriver(UUID tripId, double pickupLat, double pickupLng, int maxRingK) {
        long originH3 = h3.latLngToCell(pickupLat, pickupLng, H3_RESOLUTION);

        for (int k = 1; k <= maxRingK; k++) {
            // gridDisk(origin, 1) returns center hexagon + 6 equidistant neighbors (7 cells)
            List<Long> ringCells = h3.gridDisk(originH3, k);
            Set<String> candidateDriverIds = new HashSet<>();

            for (Long cell : ringCells) {
                Set<String> driversInCell = redis.opsForSet().members("h3:cell:" + Long.toHexString(cell));
                if (driversInCell != null) {
                    candidateDriverIds.addAll(driversInCell);
                }
            }

            if (candidateDriverIds.isEmpty()) continue;

            // Rank candidates by road-network ETA (stubbed sorting by road travel time)
            List<UUID> rankedDrivers = rankByRoadNetworkEta(pickupLat, pickupLng, candidateDriverIds);

            for (UUID candidateId : rankedDrivers) {
                String lockKey = "lock:driver:" + candidateId;
                // Atomic SET NX EX 15: Guarantees two concurrent trips never offer to the same driver
                Boolean locked = redis.opsForValue().setIfAbsent(
                    lockKey, tripId.toString(), Duration.ofSeconds(15)
                );
                if (Boolean.TRUE.equals(locked)) {
                    return Optional.of(candidateId); // Proceed to send push offer to this driver
                }
            }
        }
        return Optional.empty();
    }

    private List<UUID> rankByRoadNetworkEta(double pickupLat, double pickupLng, Set<String> driverIds) {
        return driverIds.stream().map(UUID::fromString).limit(10).toList();
    }
}

