 * FLOW 1: MINUTE-BUCKET POLLER -> HASHED WHEEL TIMER -> KAFKA DISPATCH
 * ============================================================================
 * [Poller (Shard 42)] --(Every 5s)--> Query DB: (minuteBucket=M, shardId=42)
 *   --> Claim 2,000 slots in batch TX -> Schedule in Netty HashedWheelTimer
 *   --> Tick fires at exact millisecond -> Publish to Kafka "tasks-p0"
 *
 * ============================================================================
 * FLOW 2: WORKER LEASE HEARTBEAT, ZOMBIE FENCING & CRON ROLL-FORWARD
 * ============================================================================
 * [Worker] <--(Consume)-- [Kafka]
 *   1. Acquire Lease: UPDATE job_executions SET status='RUNNING', lease=now+30s
 *      WHERE execution_id=? AND fencing_token=2
 *   2. Execute Target HTTP POST with header "X-Fencing-Token: 2"
 *   3. On 200 OK: Mark SUCCEEDED + Compute next Cron timestamp -> Insert new ScheduleSlot!
 *   4. On 5xx/Timeout: If attempt < maxRetries, insert ScheduleSlot(now + 2^attempt + jitter)
 */

package com.cloud.scheduler.engine;

import com.cloud.scheduler.domain.*;
import io.netty.util.HashedWheelTimer;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.scheduling.support.CronExpression;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.*;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;

@Service
public class PartitionedScheduleCoordinator {

    // 512 wheel buckets, 100ms per tick -> O(1) timer insertion and cancellation
    private final HashedWheelTimer timingWheel = new HashedWheelTimer(100, TimeUnit.MILLISECONDS, 512);
    private final JdbcTemplate jdbc;
    private final KafkaTemplate<String, String> kafka;

    public PartitionedScheduleCoordinator(JdbcTemplate jdbc, KafkaTemplate<String, String> kafka) {
        this.jdbc = jdbc;
        this.kafka = kafka;
    }

    // FLOW 1: Poll a specific (minuteBucket, shardId) owned by this node via Etcd lease
    @Transactional
    public void pollBucketAndLoadWheel(long minuteBucket, int shardId) {
        String sql = """
            UPDATE schedule_slots
               SET claimed = true
             WHERE minute_bucket_epoch_min = ?
               AND shard_id = ?
               AND claimed = false
         RETURNING job_id, next_run_at_epoch_ms, attempt_no
            """;

        List<SlotRow> claimedSlots = jdbc.query(
            sql,
            (rs, rowNum) -> new SlotRow(
                UUID.fromString(rs.getString("job_id")),
                rs.getLong("next_run_at_epoch_ms"),
                rs.getInt("attempt_no")
            ),
            minuteBucket, shardId
        );

        long nowMs = System.currentTimeMillis();
        for (SlotRow slot : claimedSlots) {
            UUID executionId = UUID.randomUUID();
            long fencingToken = slot.attemptNo() + 1L;

            jdbc.update("""
                INSERT INTO job_executions (execution_id, job_id, scheduled_at_epoch_ms, attempt_no, fencing_token, status)
                VALUES (?, ?, ?, ?, ?, 'DISPATCHED')
                """, executionId, slot.jobId(), slot.nextRunAtMs(), slot.attemptNo(), fencingToken
            );

            long delayMs = Math.max(0L, slot.nextRunAtMs() - nowMs);
            timingWheel.newTimeout(timeout -> {
                String msg = executionId + ":" + slot.jobId() + ":" + fencingToken;
                kafka.send("tasks-p1-standard", slot.jobId().toString(), msg);
            }, delayMs, TimeUnit.MILLISECONDS);
        }
    }

    // FLOW 2: Complete execution with Fencing Token verification & schedule next Cron/Retry slot
    @Transactional
    public boolean completeAndRollForward(
        UUID executionId,
        UUID jobId,
        long workerFencingToken,
        boolean success,
        String cronExpr,
        String timezone,
        int currentAttempt,
        int maxRetries
    ) {
        // Conditional update: rejects stale/zombie worker if fencing_token has moved ahead!
        int updated = jdbc.update("""
            UPDATE job_executions
               SET status = ?, finished_at = NOW()
             WHERE execution_id = ? AND fencing_token = ? AND status = 'RUNNING'
            """,
            success ? ExecutionStatus.SUCCEEDED.name() : ExecutionStatus.FAILED.name(),
            executionId, workerFencingToken
        );

        if (updated == 0) {
            return false; // Zombie worker fenced out!
        }

        if (success && cronExpr != null) {
            // Compute next recurring cron timestamp
            CronExpression cron = CronExpression.parse(cronExpr);
            ZonedDateTime nextRun = cron.next(ZonedDateTime.now(ZoneId.of(timezone)));
            if (nextRun != null) {
                insertScheduleSlot(jobId, nextRun.toInstant().toEpochMilli(), 0);
            }
        } else if (!success && currentAttempt < maxRetries) {
            // Exponential backoff + full jitter
            long baseDelayMs = (1L << currentAttempt) * 1000L;
            long jitterMs = ThreadLocalRandom.current().nextLong(0, 1000);
            insertScheduleSlot(jobId, System.currentTimeMillis() + baseDelayMs + jitterMs, currentAttempt + 1);
        }
        return true;
    }

    private void insertScheduleSlot(UUID jobId, long nextRunAtMs, int attemptNo) {
        long minuteBucket = nextRunAtMs / 60_000L;
        int shardId = Math.floorMod(jobId.hashCode(), 256);
        jdbc.update("""
            INSERT INTO schedule_slots (minute_bucket_epoch_min, shard_id, next_run_at_epoch_ms, job_id, attempt_no, claimed)
            VALUES (?, ?, ?, ?, ?, false)
            """, minuteBucket, shardId, nextRunAtMs, jobId, attemptNo
        );
    }

    private record SlotRow(UUID jobId, long nextRunAtMs, int attemptNo) {}
}

