/*
 * ============================================================================
 * FLOW 1: GORILLA TIME-SERIES COMPRESSION (16 BYTES -> 1.37 BYTES/SAMPLE)
 * ============================================================================
 * Sample 1: (t=1000, v=12.5) -> Stored as header (64b timestamp + 64b double)
 * Sample 2: (t=1010, v=12.5) -> dt=10 (stored in header), XOR(12.5, 12.5)=0 -> 1 bit ('0')!
 * Sample 3: (t=1020, v=12.5) -> dod=(1020-1010)-10 = 0 -> 1 bit ('0') + XOR=0 -> 1 bit ('0')
 *   => Total for Sample 3 = 2 BITS (0.25 bytes instead of 16 bytes = 64x compression!)
 *
 * ============================================================================
 * FLOW 2: INVERTED INDEX ROARING BITMAP INTERSECTION FOR PROMQL QUERIES
 * ============================================================================
 * Query: http_requests_total{service="checkout", status="500"}
 *   1. Posting(" __name__=http_requests_total") -> Bitmap [10, 24, 88, 105, 992]
 *   2. Posting("service=checkout")              -> Bitmap [24, 88, 410]
 *   3. Posting("status=500")                    -> Bitmap [24, 992]
 *   4. Bitwise AND across all 3 Bitmaps         => Series ID [24] (0.02ms!)
 */

package com.observability.telemetry.tsdb;

import com.observability.telemetry.domain.Label;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class GorillaChunkAndInvertedIndex {

    // Simplified Inverted Index mapping "labelName=labelValue" -> Sorted Set/Bitmap of 32-bit local Series Ordinals
    private final Map<String, BitSet> invertedIndex = new ConcurrentHashMap<>();
    private final Map<Integer, GorillaCompressor> activeHeadChunks = new ConcurrentHashMap<>();

    // FLOW 1: Facebook Gorilla Delta-of-Delta + XOR Floating-Point Compressor
    public static final class GorillaCompressor {
        private long prevTimestamp = 0;
        private long prevDelta = 0;
        private long prevValueBits = 0;
        private int sampleCount = 0;

        // Bit-packing buffer
        private final ByteArrayBitOutput bitOut = new ByteArrayBitOutput();

        public synchronized void append(long timestampSec, double value) {
            long valueBits = Double.doubleToRawLongBits(value);

            if (sampleCount == 0) {
                // First sample: write raw 64-bit timestamp and 64-bit IEEE-754 value
                bitOut.writeBits(timestampSec, 64);
                bitOut.writeBits(valueBits, 64);
                prevTimestamp = timestampSec;
                prevValueBits = valueBits;
                sampleCount++;
                return;
            }

            // 1. Compress Timestamp using Delta-of-Delta
            long delta = timestampSec - prevTimestamp;
            long deltaOfDelta = delta - prevDelta;

            if (deltaOfDelta == 0) {
                bitOut.writeBit(0); // 1 bit for constant scrape interval!
            } else if (deltaOfDelta >= -63 && deltaOfDelta <= 64) {
                bitOut.writeBits(0b10, 2);
                bitOut.writeBits(deltaOfDelta & 0x7FL, 7);
            } else {
                bitOut.writeBits(0b1111, 4);
                bitOut.writeBits(deltaOfDelta, 32);
            }
            prevDelta = delta;
            prevTimestamp = timestampSec;

            // 2. Compress Value using IEEE-754 XOR against previous value
            long xor = valueBits ^ prevValueBits;
            if (xor == 0) {
                bitOut.writeBit(0); // 1 bit when gauge/counter value hasn't changed!
            } else {
                bitOut.writeBit(1);
                int leadingZeros = Math.min(31, Long.numberOfLeadingZeros(xor));
                int trailingZeros = Long.numberOfTrailingZeros(xor);
                int meaningfulBits = 64 - leadingZeros - trailingZeros;

                bitOut.writeBits(leadingZeros, 5);
                bitOut.writeBits(meaningfulBits - 1, 6);
                bitOut.writeBits(xor >>> trailingZeros, meaningfulBits);
            }
            prevValueBits = valueBits;
            sampleCount++;
        }

        public byte[] toCompressedBytes() {
            return bitOut.toByteArray();
        }
    }

    // FLOW 2: Register series in Inverted Index & execute fast Bitwise AND query
    public void indexAndAppendSample(int localSeriesOrdinal, List<Label> labels, long tsSec, double value) {
        for (Label label : labels) {
            String key = label.name() + "=" + label.value();
            BitSet postings = invertedIndex.computeIfAbsent(key, k -> new BitSet());
            synchronized (postings) {
                postings.set(localSeriesOrdinal);
            }
        }
        activeHeadChunks
            .computeIfAbsent(localSeriesOrdinal, id -> new GorillaCompressor())
            .append(tsSec, value);
    }

    // Resolves matching Series Ordinals in O(1) bitwise words via Inverted Index intersection
    public List<Integer> resolveSeriesByMatchers(List<Label> matchers) {
        if (matchers.isEmpty()) return List.of();

        BitSet result = null;
        for (Label matcher : matchers) {
            BitSet posting = invertedIndex.get(matcher.name() + "=" + matcher.value());
            if (posting == null) return List.of(); // Short-circuit: zero matches

            synchronized (posting) {
                if (result == null) {
                    result = (BitSet) posting.clone();
                } else {
                    result.and(posting); // Hardware 64-bit word bitwise intersection!
                }
            }
            if (result.isEmpty()) return List.of();
        }

        List<Integer> matchedSeries = new ArrayList<>(result.cardinality());
        for (int ordinal = result.nextSetBit(0); ordinal >= 0; ordinal = result.nextSetBit(ordinal + 1)) {
            matchedSeries.add(ordinal);
        }
        return matchedSeries;
    }

    // Minimal bit-stream helper
    private static final class ByteArrayBitOutput {
        private final java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream(128);
        private long currentByte = 0;
        private int bitsLeft = 8;

        void writeBit(int bit) { writeBits(bit & 1L, 1); }
        void writeBits(long value, int numBits) {
            while (numBits > 0) {
                int shift = Math.min(numBits, bitsLeft);
                long mask = (1L << shift) - 1L;
                long bits = (value >>> (numBits - shift)) & mask;
                currentByte = (currentByte << shift) | bits;
                bitsLeft -= shift;
                numBits -= shift;
                if (bitsLeft == 0) {
                    out.write((int) currentByte);
                    currentByte = 0;
                    bitsLeft = 8;
                }
            }
        }
        byte[] toByteArray() { return out.toByteArray(); }
    }
}

