}

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY videos_metadata (Sharded MySQL (Vitess)) {
  [PK ] video_id               VARCHAR(16)
  [IDX] creator_id             UUID
        title                  VARCHAR(255)
        status                 ENUM('UPLOADING','TRANSCODING','READY')
        duration_seconds       INT
}

ENTITY transcode_renditions (Sharded MySQL (Vitess)) {
  [PK ] rendition_id           UUID
  [FK ] video_id               VARCHAR(16)
        profile                ENUM('360p','720p','1080p','4K')
        codec                  ENUM('H264','VP9','AV1')
        playlist_s3_uri        VARCHAR(512)
}

ENTITY gop_video_segments (S3 Origin + ISP Edge CDN Cache) {
  [PK ] rendition_id           UUID (Composite PK)
  [PK ] segment_seq_no         INT (0..N, 4s GOP)
        fmp4_cdn_path          VARCHAR (/v/{id}/1080p/seg_N.m4s)
        size_bytes             INT
}

// Relationships: videos_metadata --(1 : N (encoded profiles))--> transcode_renditions --(1 : N (4-second fMP4 chunks))--> gop_video_segments

/*
 * ============================================================================
 * FLOW 1: GOP-ALIGNED PARALLEL TRANSCODING DAG
 * ============================================================================
 * [Raw Video (600s)] -> [Demuxer: Split at IDR Keyframes into 150 x 4s GOPs]
 *   -> Enqueue 150 * 4 profiles = 600 independent SegmentTasks to Kafka
 *   -> Workers encode `seg_0042_720p.m4s` in parallel (takes ~2s wall-clock!)
 *   -> Redis Atomic Counter `DECR dag:fastlane:{videoId}` == 0
 *   -> Generate `master.m3u8` -> Update Video status = READY!
 *
 * ============================================================================
 * FLOW 2: HLS MASTER MANIFEST (.m3u8) & ABR SEGMENT STREAMING
 * ============================================================================
 * #EXTM3U
 * #EXT-X-STREAM-INF:BANDWIDTH=850000,RESOLUTION=640x360,CODECS="avc1.64001e,mp4a.40.2"
 * https://cdn.youtube.com/v/dQw4w9WgXcQ/360p/playlist.m3u8?token=hmac_sig...
 * #EXT-X-STREAM-INF:BANDWIDTH=2800000,RESOLUTION=1280x720,CODECS="vp09.00.31.08,opus"
 * https://cdn.youtube.com/v/dQw4w9WgXcQ/720p/playlist.m3u8?token=hmac_sig...
 * #EXT-X-STREAM-INF:BANDWIDTH=5200000,RESOLUTION=1920x1080,CODECS="av01.0.08M.08,opus"
 * https://cdn.youtube.com/v/dQw4w9WgXcQ/1080p/playlist.m3u8?token=hmac_sig...
 */

package com.youtube.streaming.service;

import com.youtube.streaming.domain.VideoCodec;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;

@Service
public class VideoTranscodingAndPlaybackService {

    private final StringRedisTemplate redis;
    private final KafkaTemplate<String, String> kafka;
    private static final byte[] CDN_HMAC_SECRET = "edge-cdn-signing-secret-key-2026".getBytes(StandardCharsets.UTF_8);

    public record RenditionSpec(String profileName, int width, int height, int bitrateKbps, VideoCodec codec, boolean fastLane) {}
    public record GopChunkDescriptor(int gopIndex, long startMs, long durationMs, String s3ByteRange) {}

    private static final List<RenditionSpec> ABR_LADDER = List.of(
        new RenditionSpec("360p_h264",  640,  360,  850,   VideoCodec.H264, true),
        new RenditionSpec("720p_h264",  1280, 720,  2800,  VideoCodec.H264, true),
        new RenditionSpec("1080p_vp9",  1920, 1080, 4500,  VideoCodec.VP9,  false),
        new RenditionSpec("2160p_av1",  3840, 2160, 12000, VideoCodec.AV1,  false)
    );

    public VideoTranscodingAndPlaybackService(StringRedisTemplate redis, KafkaTemplate<String, String> kafka) {
        this.redis = redis;
        this.kafka = kafka;
    }

    // FLOW 1: Fan-out GOP-aligned 4-second chunks across GPU/ASIC Transcoding Workers
    public void dispatchParallelGopTranscoding(String videoId, List<GopChunkDescriptor> gopChunks) {
        long fastLaneTasks = gopChunks.size() * ABR_LADDER.stream().filter(RenditionSpec::fastLane).count();
        redis.opsForValue().set("dag:fastlane:remaining:" + videoId, String.valueOf(fastLaneTasks));

        for (RenditionSpec spec : ABR_LADDER) {
            String topic = spec.fastLane() ? "transcode-p0-fastlane" : "transcode-p1-quality";
            for (GopChunkDescriptor gop : gopChunks) {
                String taskPayload = String.format(
                    "%s|%d|%s|%d|%d|%s",
                    videoId, gop.gopIndex(), spec.profileName(), spec.height(), spec.bitrateKbps(), gop.s3ByteRange()
                );
                kafka.send(topic, videoId + ":" + gop.gopIndex(), taskPayload);
            }
        }
    }

    // Called by Worker when a single 4-second GOP chunk finishes encoding
    public boolean onGopChunkTranscoded(String videoId, boolean isFastLane) {
        if (!isFastLane) return false;

        Long remaining = redis.opsForValue().decrement("dag:fastlane:remaining:" + videoId);
        if (remaining != null && remaining == 0L) {
            // All 360p and 720p 4-second segments are ready! Publish Master HLS Manifest immediately.
            return true;
        }
        return false;
    }

    // FLOW 2: Generate HLS Master Manifest (.m3u8) with Prefix-Scoped HMAC Signed CDN URLs
    public String buildSignedHlsMasterManifest(String videoId, String viewerIpSubnet) {
        long expiresEpochSec = Instant.now().getEpochSecond() + 21_600; // 6-hour token validity
        String pathPrefix = "/v/" + videoId + "/";
        String sig = signCdnPrefix(pathPrefix, viewerIpSubnet, expiresEpochSec);

        StringBuilder m3u8 = new StringBuilder("#EXTM3U\n#EXT-X-VERSION:6\n");
        for (RenditionSpec spec : ABR_LADDER) {
            String codecTag = switch (spec.codec()) {
                case H264 -> "avc1.64001f,mp4a.40.2";
                case VP9  -> "vp09.00.41.08,opus";
                case AV1  -> "av01.0.08M.08,opus";
            };
            m3u8.append(String.format(
                "#EXT-X-STREAM-INF:BANDWIDTH=%d,RESOLUTION=%dx%d,CODECS=\"%s\"\n",
                spec.bitrateKbps() * 1000, spec.width(), spec.height(), codecTag
            ));
            m3u8.append(String.format(
                "https://edge-cdn.youtube.com%s%s/playlist.m3u8?exp=%d&sig=%s\n",
                pathPrefix, spec.profileName(), expiresEpochSec, sig
            ));
        }
        return m3u8.toString();
    }

    private String signCdnPrefix(String pathPrefix, String ipSubnet, long expiresEpochSec) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(CDN_HMAC_SECRET, "HmacSHA256"));
            String payload = pathPrefix + "|" + ipSubnet + "|" + expiresEpochSec;
            byte[] rawHmac = mac.doFinal(payload.getBytes(StandardCharsets.UTF_8));
            return Base64.getUrlEncoder().withoutPadding().encodeToString(rawHmac);
        } catch (Exception e) {
            throw new IllegalStateException("Failed to sign CDN URL", e);
        }
    }
}
